'use strict';
const DATA=JSON.parse(document.getElementById('app-data').textContent);
const KEY='honghao-questions-v1';
const TABS=[['start','从中文到英语'],['transform','三条变句路线'],['words','疑问词问什么'],['listen','听问题选回答'],['read','阅读找依据'],['practice','专项练习'],['review','错题与记录']];
const ROUTES={be:['有 be 的句子','is / are / was / were'],modal:['有情态动词','can / should / will 等'],do:['普通动词','do / does / did 帮忙']};
const ROLES={sub:'主语：说的是谁',aux:'be / 助动词 / 情态动词',verb:'动词或动作部分',wh:'疑问词：问什么',rest:'其他信息'};
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const state={tab:'start',route:'be',ex:0,step:0,wh:0,lid:0,rid:0,rq:0,filter:'choice',pid:0,teacher:!!saved.teacher,font:[19,22,25].includes(saved.font)?saved.font:19,records:saved.records&&typeof saved.records==='object'?saved.records:{},voice:saved.voice||'',rate:[0.75,0.9,1].includes(saved.rate)?saved.rate:.9};
let scratch={}, voices=[],toastTimer;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=p=>p.map(x=>x[0]).join(' ');
const norm=t=>t.toLowerCase().replace(/[‘’]/g,"'").replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim();
function persist(){try{localStorage.setItem(KEY,JSON.stringify({records:state.records,teacher:state.teacher,font:state.font,voice:state.voice,rate:state.rate}))}catch{toast('浏览器无法保存记录；可用“导出学习记录”备份。')}}
function toast(t){$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',3500)}
function note(t,bad=false){return `<div class="feedback ${bad?'bad':''}" role="status">${t}</div>`}
function sent(p,end='?'){return `<div class="sentence" lang="en">${p.map(([t,r])=>`<span class="chunk ${r}">${esc(t)}<small>${ROLES[r]}</small></span>`).join('')}<span class="punct">${end}</span></div>`}
function legend(){return `<div class="legend">${['wh','aux','sub','verb','rest'].map(r=>`<span class="${r}">${ROLES[r]}</span>`).join('')}</div>`}
function speakButton(text,label='朗读',slow=false){return `<button class="small" data-action="speak" data-text="${esc(text)}" data-slow="${slow}">▷ ${label}</button>`}
function pageHead(k,title,lead){return `<div class="eyebrow">HONGHAO · QUESTION LAB / ${k}</div><h1>${title}</h1><p class="lead">${lead}</p>`}
function allItems(){return [...DATA.practice,...DATA.listening.map(q=>({...q,prompt:q.q,kind:'listen'})),...DATA.readings.flatMap((r,ri)=>r.questions.map((q,qi)=>({id:`${r.id}q${qi+1}`,prompt:q[0],kind:'read',ri,qi})))];}
function record(id,correct,response){const old=state.records[id]||{};state.records[id]={tries:(old.tries||0)+1,lastCorrect:correct,wrongEver:!!old.wrongEver||!correct,response,updated:new Date().toISOString()};persist()}
function recordClass(id){return state.records[id]?(state.records[id].lastCorrect?'done':'wrong'):''}
function shell(){
 document.documentElement.style.setProperty('--size',state.font+'px');
 $('#nav').innerHTML=TABS.map(([id,title],i)=>`<button data-action="tab" data-id="${id}" class="${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${title}</button>`).join('');
 $('#teacher').textContent=state.teacher?'教师解析：开':'学生模式';$('#teacher').setAttribute('aria-pressed',state.teacher);
 $('#fontsize').textContent=state.font===19?'字号 A+':state.font===22?'字号 A++':'字号 标准';
 const stats=Object.values(state.records);$('#rail-progress').textContent=`${stats.length} / 102 题已作答`;$('#rail-bar').style.width=(stats.length/102*100)+'%';
 const fns={start:renderStart,transform:renderTransform,words:renderWords,listen:renderListen,read:renderRead,practice:renderPractice,review:renderReview};
 $('#content').innerHTML=(state.teacher?'<p class="teacher-note">教师解析已开启：可提前查看答案。课堂检测时可切回学生模式。</p>':'')+fns[state.tab]();
}
function renderStart(){return pageHead('01','先看懂，英语怎样提问','从熟悉的句子开始：找主语、看动词，再决定怎样提问。今天不必一次学完。')+`
<div class="grid3"><div class="stat"><strong>3 条</strong><span>问句结构路线</span></div><div class="stat"><strong>60 组</strong><span>陈述句 → 问句</span></div><div class="stat"><strong>102 题</strong><span>听力 · 阅读 · 专项</span></div></div>
<section class="panel" style="margin-top:20px"><span class="tag">第一步 · 中英对照</span><h2 style="margin-top:12px">意思相同，提问的办法不同</h2><div class="scroll"><table><thead><tr><th>中文表达</th><th>英文表达</th></tr></thead><tbody><tr><td>你喜欢英语。</td><td class="en">You like English.</td></tr><tr><td>你喜欢英语<strong>吗</strong>？</td><td class="en"><b class="aux">Do</b> you <b class="verb">like</b> English?</td></tr><tr><td>你喜欢<strong>什么</strong>？</td><td class="en"><b class="wh">What</b> <b class="aux">do</b> you <b class="verb">like</b>?</td></tr></tbody></table></div><div class="callout">中文常用“吗”、疑问词和语气来提问；英语的直接问句通常还会调整顺序，或加入帮助提问的词。这是两种语言的表达习惯，不适合按中文词序逐字翻译。</div><p class="muted">中文的“什么”常留在要问的位置；英语直接提问时，what 通常放到前面。这里先学常见形式，后面再看例外。</p></section>
<section class="panel"><span class="tag">第二步 · 先分问句类型</span><div class="grid2" style="margin-top:16px"><div><h3>一般疑问句：确认是否</h3><p class="en">Do you like English?</p><p class="zh">你喜欢英语吗？</p><p class="tip">常用 Yes / No 回答，也可以补充说明。听到回答时仍要听完整。</p>${speakButton('Do you like English? Yes, I do.','听问答')}</div><div><h3>特殊疑问句：询问信息</h3><p class="en"><span class="wh">What</span> do you like?</p><p class="zh">你喜欢什么？</p><p class="tip">要给出对应信息，如 English。只说 Yes，通常没有回答这个问题。</p>${speakButton('What do you like? I like English.','听问答')}</div></div></section>
<section class="panel"><span class="tag">第三步 · 读懂颜色</span><h2 style="margin-top:12px">每一块在句子里做什么？</h2>${legend()}${sent([['Where','wh'],['does','aux'],['he','sub'],['live','verb']])}<p class="zh">他住在哪里？</p><div class="grid2"><p class="tip">主语是“说的是谁”：这里是 he。<br>live 表示动作或情况。does 在这里帮助提问，本身不翻译成“做”。</p><p class="tip">先看句子里有没有 be 或情态动词；都没有时，常见的一般现在时、一般过去时问句要请 do / does / did 帮忙。</p></div><div class="actions"><button class="primary" data-action="tab" data-id="transform">开始拆解三条路线 →</button></div></section>
<details><summary>本周课堂使用建议</summary><p class="muted">周四：认识结构 → 三条路线各选几组 → 疑问词配回答。周五：简短复习 → 听问题选回答 → 阅读找依据。每条路线有20组例句，可分多次使用，不代表需要一节课全部完成。</p></details>`}
function renderTransform(){
 const list=DATA.examples.filter(e=>e.route===state.route),e=list[state.ex];
 const stages=[['陈述句',e.s,e.zh,'.'],['一般疑问句',e.y,e.yzh,'?'],['特殊疑问句',e.q,e.qzh,'?']];
 return pageHead('02','一句话，怎样一步步变成问题？','先选路线，再逐步展开。每条路线20组，先看主语与动词，再观察顺序和形式变化。')+
 `<div class="routebar">${Object.entries(ROUTES).map(([r,t])=>`<button data-action="route" data-id="${r}" class="${state.route===r?'active':''}">${t[0]}<small>${t[1]} · 20组</small></button>`).join('')}</div>${legend()}<section class="panel"><div class="summary-row"><span class="tag">${ROUTES[state.route][0]}</span><span class="counter">第 ${state.ex+1} / 20 组</span></div><div class="steps">${stages.map((s,i)=>`<span class="${i===state.step?'current':''}">${i+1} ${s[0]}</span>`).join('')}</div>${stages.slice(0,state.step+1).map((s,i)=>`<div class="${i?'compare':''}"><div class="sentence-label">${s[0]}</div>${sent(s[1],s[3])}<div class="zh">${esc(s[2])}</div>${speakButton(plain(s[1])+s[3],'听这句话')}</div>`).join('')}<div class="tip">${state.step===0?'先找到主语，再看句子里是 be、情态动词，还是普通动词。':esc(e.tip)}</div><div class="actions"><button data-action="step" data-step="${state.step-1}" ${state.step===0?'disabled':''}>← 上一步</button><button class="primary" data-action="step" data-step="${state.step+1}" ${state.step===2?'disabled':''}>${state.step===0?'变成一般疑问句':'加入疑问词'} →</button><button class="quiet" data-action="step" data-step="2">完整对照</button></div></section>
 <div class="pager"><button data-action="ex" data-index="${state.ex-1}" ${state.ex===0?'disabled':''}>上一组</button><button data-action="ex" data-index="${state.ex+1}" ${state.ex===19?'disabled':''}>下一组 →</button><span class="muted">换例句时重新从陈述句开始。</span></div><div class="jumpgrid">${list.map((_,i)=>`<button data-action="ex" data-index="${i}" class="${i===state.ex?'active':''}" aria-label="第${i+1}组">${i+1}</button>`).join('')}</div>
 <details><summary>do / does / did 怎样选？</summary><div class="scroll"><table><thead><tr><th>时间</th><th>主语</th><th>帮手</th><th>后面的动词</th></tr></thead><tbody><tr><td>一般现在时</td><td>I / you / we / they 等</td><td>do</td><td>原形</td></tr><tr><td>一般现在时</td><td>he / she / it / 单个人或事物</td><td>does</td><td>原形</td></tr><tr><td>一般过去时</td><td>各类主语</td><td>did</td><td>原形</td></tr></tbody></table></div><p class="tip">He plays → Does he play?；She went → Did she go?。这里比较的是普通动词句型；有 be 或情态动词时走另外两条路线。</p></details>`;
}
function renderWords(){const w=DATA.wh[state.wh];return pageHead('03','疑问词决定：我要找哪种答案？','把疑问词连成词组来认：how often、how long、how soon 问的内容不同。')+`
<div class="wordgrid">${DATA.wh.map((x,i)=>`<button data-action="wh" data-index="${i}" class="${i===state.wh?'active':''}"><b>${x.word}</b><small>${x.meaning}</small></button>`).join('')}</div><section class="panel" style="margin-top:20px"><span class="tag">要找的信息：${w.kind}</span><h2 class="en large" style="margin-top:14px">${w.word}</h2><p class="en">${esc(w.q)}</p><p class="zh">${w.qzh}</p>${speakButton(w.q,'听问题')}<div class="compare"><span class="sentence-label">对应的回答</span><p class="en">${esc(w.a)}</p><p class="zh">${w.azh}</p>${speakButton(w.a,'听回答')}</div><div class="tip">${w.note}</div></section>
<section class="panel"><h2>最容易混淆的四组 how</h2><div class="scroll"><table><thead><tr><th>问句</th><th>问什么</th><th>回答示例</th></tr></thead><tbody><tr><td class="en">How often…?</td><td>多久一次</td><td>Twice a week. 每周两次。</td></tr><tr><td class="en">How long…?</td><td>多久 / 多长</td><td>For two days. 两天。 / Two metres. 两米。</td></tr><tr><td class="en">How soon…?</td><td>多久以后</td><td>In two days. 两天后。</td></tr><tr><td class="en">How far…?</td><td>多远</td><td>Two kilometres. 两千米。</td></tr></tbody></table></div></section>
<details><summary>进阶①：Who called you? 为什么没有 did？</summary><div class="grid2"><div><p class="en"><span class="sub">Tom</span> called you.</p><p class="en"><span class="wh">Who</span> called you?</p><p class="zh">谁打电话给你？who 替换 Tom，本身作主语，普通肯定形式的主语问句不加 did。</p></div><div><p class="en">You called <span class="rest">Tom</span>.</p><p class="en"><span class="wh">Who</span> did you call?</p><p class="zh">你打电话给谁？主语还是 you，过去时用 did，called 还原为 call。</p></div></div><p class="tip">先找“谁做了这件事”。不能看见 who 就一律加 did，也不能一律省略 did。</p></details>
<details><summary>进阶②：Do you know where he lives? 为什么又不倒装？</summary><p class="en">Where <span class="aux">does</span> <span class="sub">he</span> <span class="verb">live</span>?</p><p class="zh">直接问：他住在哪里？</p><p class="en">Do you know <span class="wh">where</span> <span class="sub">he</span> <span class="verb">lives</span>?</p><p class="zh">你知道他住在哪里吗？</p><p class="tip">外层 Do you know… 是一般疑问句；里面 where 引导的从句用陈述语序 he lives。整句在交际中通常是在请对方提供地点信息，不能只因 Do 开头就机械地只答 Yes。</p></details><div class="actions"><button class="primary" data-action="tab" data-id="listen">去听问题 →</button></div>`}
function optionButtons(options,selected,submitted,answer,action){return `<div class="options">${options.map((o,i)=>`<button data-action="${action}" data-index="${i}" class="${selected===i?'selected':''} ${submitted&&i===answer?'correct':''} ${submitted&&selected===i&&i!==answer?'incorrect':''}" ${submitted?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>`}
function jumpButtons(items,id,action){return `<div class="jumpgrid">${items.map((x,i)=>`<button data-action="${action}" data-index="${i}" class="${i===id?'active':''} ${recordClass(x.id)}" aria-label="第${i+1}题">${i+1}</button>`).join('')}</div>`}
function renderListen(){const q=DATA.listening[state.lid],s=scratch[q.id]||{},shown=s.show??(state.teacher||s.result),types=['一般疑问句','特殊疑问句'],kinds=['是否','人或归属','活动或事物','地点','时间或时刻','原因','方式或状态','频率','时长或长度','多久以后','距离','数量或价格','选择','年龄'];return pageHead('04','先听懂问题，再选回答','24道原创听辨题。先不看文字，听两遍；再判断类型、所问信息和合适回答。')+`
<section class="panel"><div class="summary-row"><span class="tag">听力 ${state.lid+1} / 24</span><span class="muted">普通 / 慢速可重复播放</span></div><div class="audiohero"><div class="audioicon" aria-hidden="true">◖ ▮▮▮ ◗</div><h2>这句话在问什么？</h2><div class="actions" style="justify-content:center">${speakButton(q.q,'播放问题')}${speakButton(q.q,'慢速播放',true)}</div><p class="caption">语音由设备提供；若没有英语语音，请由老师朗读。</p></div><button class="small quiet" data-action="listen-text">${shown?'隐藏题干文字':'展开题干文字 / 老师朗读用'}</button>${shown?`<div class="transcript en">${esc(q.q)}</div>`:''}
<div class="stagebox"><h3>① 判断问句类型</h3><div class="pills">${types.map(x=>`<button data-action="listen-type" data-value="${x}" class="${s.type===x?'active':''}" ${s.result?'disabled':''}>${x}</button>`).join('')}</div></div>
<div class="stagebox"><h3>② 判断要找哪一种信息</h3><div class="pills">${kinds.map(x=>`<button class="small ${s.kind===x?'active':''}" data-action="listen-kind" data-value="${x}" ${s.result?'disabled':''}>${x}</button>`).join('')}</div></div><h3>③ 选择合适的回答</h3>${optionButtons(q.options,s.choice,s.result,q.answer,'listen-choice')}
<div class="actions"><button class="primary" data-action="listen-check" ${s.result?'disabled':''}>检查这三步</button>${s.result?'<button data-action="listen-retry">重新作答</button>':''}<button data-action="listen-next" ${state.lid===23?'disabled':''}>下一题 →</button></div>
${s.result?note(`<strong>${s.correct?'三步全部正确':'再核对：类型、信息和回答'}</strong><p>正确类型：${q.type}；所问信息：${q.kind}。</p><p>合适回答：${esc(q.options[q.answer])}</p><p>${q.explain}</p>`,!s.correct):state.teacher?`<details><summary>教师答案</summary><p>${q.type} · ${q.kind} · ${esc(q.options[q.answer])}</p><p>${q.explain}</p></details>`:''}</section>${jumpButtons(DATA.listening,state.lid,'listen-jump')}`}
function renderRead(){const r=DATA.readings[state.rid],q=r.questions[state.rq],id=`${r.id}q${state.rq+1}`,s=scratch[id]||{},evidence=s.evidence??s.result;return pageHead('05','把问题拆开，再回原文找依据','3篇原创短文，每篇4题。先判断问什么，再定位句子；需要时点击原文句子显示中文。')+`
<div class="pills">${DATA.readings.map((x,i)=>`<button data-action="reading" data-index="${i}" class="${state.rid===i?'active':''}">${i+1} ${x.title}</button>`).join('')}</div><div class="reading-layout"><section class="panel passage"><span class="tag">${r.tag}</span><h2 style="margin-top:14px">${r.title}</h2>${r.sentences.map(([en,zh],i)=>`<div class="line ${evidence&&q[4].includes(i+1)?'evidence':''}" data-action="line-zh" data-index="${i}" tabindex="0" role="button" aria-label="第${i+1}句，点击切换中文"><div class="en" lang="en"><span class="line-num">${i+1}</span>${esc(en)}</div>${s.lines?.includes(i)?`<div class="zh">${zh}</div>`:''}</div>`).join('')}<div class="actions">${speakButton(r.sentences.map(x=>x[0]).join(' '),'朗读全文')}<button class="small" data-action="passage-zh">${s.allZh?'收起中文':'显示全文中文'}</button></div></section><section class="panel"><span class="tag">第 ${state.rq+1} / 4 题</span><p class="questiontext">${esc(q[0])}</p>${speakButton(q[0],'听问题')}<div class="actions"><button class="small" data-action="read-hint">${s.hint?'收起问题提示':'① 拆解问题重点'}</button><button class="small" data-action="read-evidence">② ${evidence?'收起':'标出'}原文依据</button></div>${s.hint?`<div class="tip">这道题要找：<strong>${q[1]}</strong>。${q[6]?.length?sent(q[6]):''}<p>${esc(q[7])}</p></div>`:''}${optionButtons(q[2],s.choice,s.result,q[3],'read-choice')}<div class="actions"><button class="primary" data-action="read-check" ${s.result?'disabled':''}>检查答案</button>${s.result?'<button data-action="read-retry">再做一次</button>':''}<button data-action="read-next" ${state.rq===3&&state.rid===2?'disabled':''}>下一题 →</button></div>${s.result?note(`<strong>${s.correct?'回答正确':'再回原文核对'}</strong><p>${q[5]}</p><p>依据：原文第 ${q[4].join('、')} 句。</p>`,!s.correct):state.teacher?`<details><summary>教师答案与依据</summary><p>${esc(q[2][q[3]])}</p><p>${q[5]} 依据：第${q[4].join('、')}句。</p></details>`:''}<div class="jumpgrid">${r.questions.map((_,i)=>`<button data-action="read-jump" data-index="${i}" class="${i===state.rq?'active':''} ${recordClass(`${r.id}q${i+1}`)}">${i+1}</button>`).join('')}</div><p class="caption">黄色高亮标的是解题依据；翻译和提示由老师按需展开。</p></section></div>`}
const FILTERS={choice:'选择合适表达 · 18',order:'词块排序 · 24',fix:'改错 · 12',produce:'自己提问 · 12'};
function practiceList(){return DATA.practice.filter(q=>q.type===state.filter)}
function getOrder(q,s){if(!s.pool){s.pool=q.chunks.map((text,i)=>({text,i}));for(let j=s.pool.length-1;j>0;j--){const k=Math.floor(Math.random()*(j+1));[s.pool[j],s.pool[k]]=[s.pool[k],s.pool[j]]}if(s.pool.every((x,i)=>x.i===i))s.pool.reverse();s.picked=[]}return s.pool}
function renderPractice(){const list=practiceList(),q=list[state.pid],s=scratch[q.id]|| (scratch[q.id]={});let body='';
 if(q.type==='choice')body=optionButtons(q.options,s.choice,s.result,q.answer,'practice-choice');
 if(q.type==='order'){const pool=getOrder(q,s);body=`<p class="caption">点击下方词块组成问句；点击已放入的词块可撤回。词块保留原样，不需要键入问号。</p><div class="answerzone" aria-label="已排列的问句">${s.picked.length?s.picked.map(i=>`<button data-action="unpick" data-index="${i}" ${s.result?'disabled':''}>${esc(q.chunks[i])}</button>`).join(''):'<span class="muted">问句从这里开始……</span>'}</div><div class="tokens">${pool.filter(x=>!s.picked.includes(x.i)).map(x=>`<button data-action="pick" data-index="${x.i}" ${s.result?'disabled':''}>${esc(x.text)}</button>`).join('')}</div>`}
 if(['fix','produce'].includes(q.type))body=`${q.type==='fix'?`<p class="en">${esc(q.prompt)}</p><p class="caption">请把整句改正确；有回答提示的题，只改问句部分。</p>`:'<p class="caption">按提示写一个完整问句。自动核对忽略大小写和标点；其他合理表达请由老师判断。</p>'}<label class="muted" for="written">你的问句</label><textarea id="written" lang="en" placeholder="在这里写英文问句……" ${s.result?'disabled':''}>${esc(s.text||'')}</textarea>`;
 const model=q.model||(q.options?.[q.answer]);return pageHead('06','看懂以后，自己把问题问出来','选择 → 词块排序 → 改错 → 自己提问，共66题。输入题提供参考表达，不把所有不同写法都判成语法错误。')+`<div class="pills">${Object.entries(FILTERS).map(([k,t])=>`<button data-action="filter" data-id="${k}" class="${state.filter===k?'active':''}">${t}</button>`).join('')}</div><section class="panel"><span class="tag">${FILTERS[state.filter].split(' · ')[0]}</span><span class="counter">第 ${state.pid+1} / ${list.length} 题</span><h2 style="margin-top:18px">${esc(q.type==='fix'?'找出并改正问句中的问题':q.prompt)}</h2>${body}<div class="actions"><button class="primary" data-action="practice-check" ${s.result?'disabled':''}>检查答案</button><button data-action="practice-retry">重新作答</button><button data-action="practice-next" ${state.pid===list.length-1?'disabled':''}>下一题 →</button></div>${s.result?note(`<strong>${s.correct?'核对通过':['fix','produce'].includes(q.type)?'与参考表达不同，请核对结构':'再检查一下结构'}</strong><p>参考表达：<span class="en">${esc(model)}</span></p><p>${q.explain}</p>${s.correct?'':s.text?'<p>输入题可能有其他合理表达。老师确认后，可点击下方按钮记录为正确。</p><button class="small" data-action="teacher-accept">老师确认：此表达正确</button>':''}`,!s.correct):state.teacher?`<details><summary>教师参考表达</summary><p class="en">${esc(model)}</p><p>${q.explain}</p></details>`:''}</section>${jumpButtons(list,state.pid,'practice-jump')}`;
}
function renderReview(){const all=allItems(),records=state.records,done=all.filter(q=>records[q.id]),wrong=done.filter(q=>!records[q.id].lastCorrect),correct=done.filter(q=>records[q.id].lastCorrect),ever=done.filter(q=>records[q.id].wrongEver);return pageHead('07','看见问题，再练一次','这里记录本设备上的作答情况。最近一次答错的题进入待复习；重新答对后移出待复习。')+`
<div class="grid3"><div class="stat"><strong>${done.length} / 102</strong><span>已作答题目</span></div><div class="stat"><strong>${correct.length}</strong><span>最近一次答对</span></div><div class="stat"><strong>${wrong.length}</strong><span>待复习题目</span></div></div><section class="panel" style="margin-top:20px"><h2>待复习</h2>${wrong.length?wrong.map(q=>`<div class="review-card"><div><span class="tag">${q.kind==='listen'?'听力':q.kind==='read'?'阅读':FILTERS[q.type].split(' · ')[0]}</span><p class="en">${esc(q.prompt)}</p><span class="caption">累计作答 ${records[q.id].tries} 次</span></div><button class="small" data-action="review-open" data-id="${q.id}">重新练习 →</button></div>`).join(''):'<div class="empty">暂时没有待复习题。完成练习后，记录会显示在这里。</div>'}</section><section class="panel"><h2>课堂记录备份</h2><p class="muted">累计有 ${ever.length} 道题曾答错。记录保存在当前浏览器，不会自动同步到其他设备。导出文件包含作答与设置，不包含学生姓名或账号。</p><div class="actions"><button data-action="export">导出学习记录</button><button data-action="import">导入记录</button></div><p class="caption">导入时合并记录，同一道题保留时间较新的作答。</p></section><div class="actions"><a href="../english-exams-2022-2026/">进入2022—2026中考真题课堂 →</a></div>`}
function initVoice(){if(!('speechSynthesis' in window)){$('#voice-status').textContent='此浏览器不支持朗读，请由老师示范。';return}voices=speechSynthesis.getVoices().filter(v=>/^en[-_]/i.test(v.lang));const sel=$('#voice');sel.innerHTML=voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${v.lang})</option>`).join(''):'<option value="">暂无英语语音</option>';let v=voices.find(v=>v.voiceURI===state.voice)||voices.find(v=>/^en-GB$/i.test(v.lang))||voices[0];if(v){state.voice=v.voiceURI;sel.value=v.voiceURI;$('#voice-status').textContent='朗读使用设备英语语音；可选择语速，也可由老师示范。'}else $('#voice-status').textContent='此设备暂未提供英语语音；请由老师朗读，或换用提供英语语音的浏览器。'}
function speak(text,slow=false){if(!voices.length||!('speechSynthesis'in window)){toast('暂无英语语音，请由老师朗读；听力题可展开题干。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=voices.find(v=>v.voiceURI===state.voice)||voices[0];u.lang=u.voice.lang;u.rate=slow?.65:state.rate;u.onerror=()=>toast('语音播放失败，可重试或由老师示范。');speechSynthesis.speak(u)}
function scratchFor(id){return scratch[id]||(scratch[id]={})}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function go(tab){stopSpeech();state.tab=tab;history.replaceState(null,'','#'+tab);shell();window.scrollTo({top:0,behavior:'instant'})}
function resetQuestion(id){delete scratch[id];shell()}
function checkPractice(){const q=practiceList()[state.pid],s=scratchFor(q.id);let correct=false,response;
 if(q.type==='choice'){if(s.choice===undefined)return toast('先选择一个答案。');correct=s.choice===q.answer;response=q.options[s.choice]}
 else if(q.type==='order'){if(s.picked.length!==q.chunks.length)return toast('先把所有词块放入问句。');response=s.picked.map(i=>q.chunks[i]).join(' ')+'?';correct=norm(response)===norm(q.model)}
 else{if(!s.text?.trim())return toast('先写一个完整问句。');response=s.text;correct=q.accepted.some(x=>norm(x)===norm(s.text))}
 s.result=true;s.correct=correct;record(q.id,correct,response);shell();
}
document.addEventListener('input',e=>{if(e.target.id==='written'){const q=practiceList()[state.pid];scratchFor(q.id).text=e.target.value}});
document.addEventListener('change',e=>{if(e.target.id==='voice'){state.voice=e.target.value;persist()}if(e.target.id==='rate'){state.rate=Number(e.target.value);persist()}if(e.target.id==='import-file')importRecords(e.target.files[0])});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.line[role=button]')){e.preventDefault();e.target.click()}});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,n=Number(b.dataset.index),v=b.dataset.value;
 if(a==='speak'){speak(b.dataset.text,b.dataset.slow==='true');return}
 if(a==='tab'){go(b.dataset.id);return}
 if(a==='teacher'){state.teacher=!state.teacher;persist();shell();return}
 if(a==='fontsize'){state.font=state.font===19?22:state.font===22?25:19;persist();shell();return}
 if(a==='route'){state.route=b.dataset.id;state.ex=0;state.step=0;shell();return}
 if(a==='ex'){if(n>=0&&n<20){state.ex=n;state.step=0;stopSpeech();shell()}return}
 if(a==='step'){state.step=Math.max(0,Math.min(2,Number(b.dataset.step)));shell();return}
 if(a==='wh'){state.wh=n;stopSpeech();shell();return}
 if(a.startsWith('listen-')){const q=DATA.listening[state.lid],s=scratchFor(q.id);
   if(a==='listen-text')s.show=!(s.show??(state.teacher||s.result));
   if(a==='listen-type')s.type=v;if(a==='listen-kind')s.kind=v;if(a==='listen-choice')s.choice=n;
   if(a==='listen-check'){if(!s.type||!s.kind||s.choice===undefined)return toast('请完成类型、所问信息和回答三步。');s.result=true;s.correct=s.type===q.type&&s.kind===q.kind&&s.choice===q.answer;record(q.id,s.correct,{type:s.type,kind:s.kind,answer:q.options[s.choice]})}
   if(a==='listen-retry'){resetQuestion(q.id);return}
   if(a==='listen-next'){state.lid=Math.min(23,state.lid+1);stopSpeech()}
   if(a==='listen-jump'){state.lid=n;stopSpeech()}
   shell();return;
 }
 if(a==='reading'){state.rid=n;state.rq=0;stopSpeech();shell();return}
 if(a.startsWith('read-')||a==='line-zh'||a==='passage-zh'){const r=DATA.readings[state.rid],q=r.questions[state.rq],id=`${r.id}q${state.rq+1}`,s=scratchFor(id);
   if(a==='read-choice')s.choice=n;if(a==='read-hint')s.hint=!s.hint;if(a==='read-evidence')s.evidence=!(s.evidence??s.result);
   if(a==='line-zh'){s.lines=s.lines||[];s.lines=s.lines.includes(n)?s.lines.filter(x=>x!==n):[...s.lines,n]}
   if(a==='passage-zh'){s.allZh=!s.allZh;s.lines=s.allZh?r.sentences.map((_,i)=>i):[]}
   if(a==='read-check'){if(s.choice===undefined)return toast('先选择一个答案。');s.result=true;s.correct=s.choice===q[3];record(id,s.correct,q[2][s.choice])}
   if(a==='read-retry'){resetQuestion(id);return}
   if(a==='read-next'){if(state.rq<3)state.rq++;else if(state.rid<2){state.rid++;state.rq=0}stopSpeech()}
   if(a==='read-jump'){state.rq=n;stopSpeech()}
   shell();return;
 }
 if(a==='filter'){state.filter=b.dataset.id;state.pid=0;shell();return}
 if(a==='pick'||a==='unpick'){const q=practiceList()[state.pid],s=scratchFor(q.id);if(a==='pick'&&!s.picked.includes(n))s.picked.push(n);if(a==='unpick')s.picked=s.picked.filter(i=>i!==n);shell();return}
 if(a==='practice-choice'){scratchFor(practiceList()[state.pid].id).choice=n;shell();return}
 if(a==='practice-check'){checkPractice();return}
 if(a==='practice-retry'){resetQuestion(practiceList()[state.pid].id);return}
 if(a==='practice-next'){state.pid=Math.min(practiceList().length-1,state.pid+1);shell();return}
 if(a==='practice-jump'){state.pid=n;shell();return}
 if(a==='teacher-accept'){const q=practiceList()[state.pid],s=scratchFor(q.id);s.correct=true;record(q.id,true,s.text);shell();return}
 if(a==='review-open'){const q=allItems().find(q=>q.id===b.dataset.id);delete scratch[q.id];if(q.kind==='listen'){state.lid=DATA.listening.findIndex(x=>x.id===q.id);go('listen')}else if(q.kind==='read'){state.rid=q.ri;state.rq=q.qi;go('read')}else{state.filter=q.type;state.pid=practiceList().findIndex(x=>x.id===q.id);go('practice')}return}
 if(a==='export'){const blob=new Blob([JSON.stringify({app:KEY,version:1,exported:new Date().toISOString(),records:state.records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='英语问句学习记录-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 if(a==='import'){$('#import-file').click();return}
});
async function importRecords(file){if(!file)return;try{if(file.size>2e6)throw Error('文件太大');const d=JSON.parse(await file.text());if(d.app!==KEY||d.version!==1||!d.records||typeof d.records!=='object'||Array.isArray(d.records))throw Error('不是本模块的记录文件');const allowed=new Set(allItems().map(q=>q.id));let count=0;for(const[id,r]of Object.entries(d.records)){if(!allowed.has(id)||!r||typeof r.lastCorrect!=='boolean'||!Number.isInteger(r.tries)||r.tries<1||!Number.isFinite(Date.parse(r.updated)))continue;const old=state.records[id];if(!old||Date.parse(r.updated)>Date.parse(old.updated)){state.records[id]={tries:r.tries,lastCorrect:r.lastCorrect,wrongEver:!!r.wrongEver,response:typeof r.response==='string'?r.response.slice(0,2000):r.response,updated:r.updated};count++}}persist();scratch={};shell();toast(`已合并 ${count} 条较新记录。`)}catch(err){toast('导入失败：'+err.message)}finally{$('#import-file').value=''}}
const hash=location.hash.slice(1);if(TABS.some(t=>t[0]===hash))state.tab=hash;
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(TABS.some(t=>t[0]===h)){state.tab=h;shell()}});
$('#rate').value=state.rate;shell();initVoice();if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',initVoice);
